    for (const tok of text.trim().split(/[\s|]+/).filter(Boolean)) {
      const [n, len] = tok.split(':');
      if (len) d = +len;
      if (n !== 'r') out.push([b, midi(n), d]);
      b += d;
    }
    return out;
